<?php
namespace Sis_medico\Services;
class ClinicalArchitectureAuditService
{public function inspect(){$roots=array(app_path('Http/Controllers/hospital'),app_path('Http/Controllers/hc4'),app_path('Http/Controllers/hc_admision'));$items=array();foreach($roots as $root){if(!is_dir($root))continue;$iterator=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS));foreach($iterator as $file){if($file->getExtension()!=='php')continue;$source=@file_get_contents($file->getPathname());$lines=substr_count($source,"\n")+1;$writes=preg_match_all('/(::create|::insert|insertGetId|->save\(|->update\(|->delete\()/',$source,$matches);if($lines>1500||$writes>35)$items[]=array('file'=>str_replace(base_path().DIRECTORY_SEPARATOR,'',$file->getPathname()),'lines'=>$lines,'writes'=>$writes);}}usort($items,function($a,$b){return $b['lines']-$a['lines'];});return array('pending'=>count($items),'controllers'=>$items,'criteria'=>array('large_controller_lines'=>1500,'absolute_writes'=>35));}}
